 10	    public static void main(String[] args) {
 11	        createGraph();
 12	        searchWay();
 13	        showResult();
 14	    }
 15	
 16	    private static void createGraph() {
 17	        boolean[] states = {true, false};
 18	        for (boolean wolf : states) {
 19	            for (boolean sheep : states) {
 20	                for (boolean vegetable : states) {
 21	                    for (boolean farmer : states) {
 22	                        if (!isValid(wolf, sheep, vegetable, farmer)) {
 23	                            continue;
 24	                        }
 25	                        Node node = new Node(wolf, sheep, vegetable, farmer);
 26	                        node.setIndex(nodes.size());
 27	                        nodes.add(node);
 28	                    }
 29	                }
 30	            }
 31	        }
 32	        edges = new int[nodes.size()][nodes.size()];
 33	        for (int i = 0; i < nodes.size(); i++) {
 34	            for (int j = 0; j < nodes.size(); j++) {
 35	                edges[i][j] = canConnect(nodes.get(i), nodes.get(j)) ? 1 : 0;
 36	            }
 37	        }
 38	        visit = new boolean[nodes.size()];
 39	    }
 40	
 41	    private static void searchWay() {
 42	        int start = 0;
 43	        int last = 0;
 44	        for (int i = 0; i < nodes.size(); i++) {
 45	            Node node = nodes.get(i);
 46	            if (!node.getFarmer() && !node.getSheep() && !node.getVegetable() && !node.getWolf()) {
 47	                start = i;
 48	            }
 49	            if (node.getFarmer() && node.getSheep() && node.getVegetable() && node.getWolf()) {
 50	                last = i;
 51	            }
 52	        }
 53	        DFS(nodes.get(start), nodes.get(last));
 54	    }
 55	
 56	    private static void DFS(Node startNode, Node lastNode) {
 57	        stack.push(startNode);
 58	        visit[startNode.index] = true;
 59	        while (!stack.isEmpty()) {
 60	            int index = stack.getTop().getIndex();
 61	            if (index == lastNode.index) {
 62	                results.add(stack.getList());
 63	                stack.pop();
 64	                visit[lastNode.index] = false;
 65	                break;
 66	            }
 67	            while (startNode.flag < nodes.size()) {
 68	                if (edges[index][startNode.flag] == 1 && !visit[startNode.flag]) {
 69	                    DFS(nodes.get(startNode.flag), lastNode);
 70	                }
 71	                startNode.flag++;
 72	            }
 73	            if (startNode.flag == nodes.size()) {
 74	                stack.pop();
 75	                startNode.flag = 0;
 76	                visit[startNode.index] = false;
 77	                break;
 78	            }
 79	        }
 80	    }
 81	
 82	    private static void showResult() {
 83	        for (int i = 0; i < results.size(); i++) {
 84	            System.out.println("第" + (i + 1) + "种答案");
 85	            ArrayList<Node> result = results.get(i);
 86	            for (int j = 0; j < result.size() - 1; j++) {
 87	                Node now = result.get(j);
 88	                Node next = result.get(j + 1);
 89	                StringBuilder sb = new StringBuilder("农夫");
 90	                if (now.getSheep() != next.getSheep()) {
 91	                    sb.append("带着羊");
 92	                } else if (now.getWolf() != next.getWolf()) {
 93	                    sb.append("带着狼");
 94	                } else if (now.getVegetable() != next.getVegetable()) {
 95	                    sb.append("带着菜");
 96	                } else {
 97	                    sb.append("什么都不带");
 98	                }
 99	                if (next.getFarmer()) {
100	                    sb.append("过到对岸。");
101	                } else {
102	                    sb.append("回到原岸。");
103	                }
104	                System.out.println(sb.toString());
105	            }
106	            System.out.println();
107	        }
108	    }
109	
110	    private static boolean isValid(boolean wolf, boolean sheep, boolean vegetable, boolean farmer) {
111	        return farmer == sheep || (wolf != sheep && sheep != vegetable);
112	    }
113	
114	    private static boolean canConnect(Node i, Node j) {
115	        int count = 0;
116	        if (i.getWolf() != j.getWolf()) {
117	            count++;
118	        }
119	        if (i.getSheep() != j.getSheep()) {
120	            count++;
121	        }
122	        if (i.getVegetable() != j.getVegetable()) {
123	            count++;
124	        }
125	        return i.getFarmer() != j.getFarmer() && count <= 1;
126	    }
127	}
