132	    private boolean vegetable;
133	    private boolean farmer;
134	    public int index;
135	    public int flag = 0;
136	
137	    public Node(boolean wolf, boolean sheep, boolean vegetable, boolean farmer) {
138	        this.wolf = wolf;
139	        this.sheep = sheep;
140	        this.vegetable = vegetable;
141	        this.farmer = farmer;
142	    }
143	
144	    public void setIndex(int index) {
145	        this.index = index;
146	    }
147	
148	    public int getIndex() {
149	        return index;
150	    }
151	
152	    public boolean getWolf() {
153	        return wolf;
154	    }
155	
156	    public boolean getSheep() {
157	        return sheep;
158	    }
159	
160	    public boolean getVegetable() {
161	        return vegetable;
162	    }
163	
164	    public boolean getFarmer() {
165	        return farmer;
166	    }
167	}
168	
169	class Stack {
170	    private ArrayList<Node> list;
171	
172	    public Stack() {
173	        list = new ArrayList<>();
174	    }
175	
176	    public void push(Node node) {
177	        list.add(node);
178	    }
179	
180	    public Node pop() {
181	        return list.remove(list.size() - 1);
182	    }
183	
184	    public Node getTop() {
185	        return list.get(list.size() - 1);
186	    }
187	
188	    public boolean isEmpty() {
189	        return list.isEmpty();
190	    }
191	
192	    @SuppressWarnings("unchecked")
193	    public ArrayList<Node> getList() {
194	        return (ArrayList<Node>)list.clone();
195	    }
196	}

